using Acme.Projects;
using Acme.Tenants;
using Microsoft.AspNetCore.Mvc;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddScoped<ITenantDirectory, SqlTenantDirectory>();
builder.Services.AddScoped<IProjectStore, SqlProjectStore>();

var app = builder.Build();

app.MapGet("/healthz", () => Results.Ok());

app.MapGet("/projects", async (
    [FromHeader(Name = "X-Tenant-Id")] string tenant, ITenantDirectory tenants, IProjectStore store) =>
{
    if (!await tenants.IsActiveAsync(tenant))
    {
        return Results.StatusCode(StatusCodes.Status403Forbidden);
    }
    return Results.Ok(await store.ListAsync(tenant));
});

app.MapPost("/projects", async (
    [FromHeader(Name = "X-Tenant-Id")] string tenant, CreateProject body, ITenantDirectory tenants, IProjectStore store) =>
{
    if (!await tenants.IsActiveAsync(tenant))
    {
        return Results.StatusCode(StatusCodes.Status403Forbidden);
    }
    var id = await store.CreateAsync(tenant, body);
    return Results.Created($"/projects/{id}", new { id });
});

app.MapDelete("/projects/{id:int}", async (
    int id, [FromHeader(Name = "X-Tenant-Id")] string tenant, ITenantDirectory tenants, IProjectStore store) =>
{
    if (!await tenants.IsActiveAsync(tenant))
    {
        return Results.StatusCode(StatusCodes.Status403Forbidden);
    }
    await store.DeleteAsync(tenant, id);
    return Results.NoContent();
});

app.Run();

