namespace Acme.Tenants;

public sealed class ActiveTenantFilter(ITenantDirectory tenants) : IEndpointFilter
{
    public async ValueTask<object?> InvokeAsync(EndpointFilterInvocationContext context, EndpointFilterDelegate next)
    {
        var tenant = context.HttpContext.Request.Headers["X-Tenant-Id"].ToString();
        if (!await tenants.IsActiveAsync(tenant))
        {
            return Results.StatusCode(StatusCodes.Status403Forbidden);
        }
        return await next(context);
    }
}

using Acme.Projects;
using Acme.Tenants;
using Microsoft.AspNetCore.Mvc;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddScoped<ITenantDirectory, SqlTenantDirectory>();
builder.Services.AddScoped<IProjectStore, SqlProjectStore>();

var app = builder.Build();

var api = app.MapGroup("").AddEndpointFilter<ActiveTenantFilter>();

api.MapGet("/healthz", () => Results.Ok());

api.MapGet("/projects", async ([FromHeader(Name = "X-Tenant-Id")] string tenant, IProjectStore store) =>
    Results.Ok(await store.ListAsync(tenant)));

api.MapPost("/projects", async ([FromHeader(Name = "X-Tenant-Id")] string tenant, CreateProject body, IProjectStore store) =>
{
    var id = await store.CreateAsync(tenant, body);
    return Results.Created($"/projects/{id}", new { id });
});

api.MapDelete("/projects/{id:int}", async (int id, [FromHeader(Name = "X-Tenant-Id")] string tenant, IProjectStore store) =>
{
    await store.DeleteAsync(tenant, id);
    return Results.NoContent();
});

app.Run();
